WITH scored AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, RANK() OVER (ORDER BY amount DESC NULLS FIRST) AS amount_rank, NTILE(5) OVER w_running AS amount_bucket, LAST_VALUE(amount) IGNORE NULLS OVER w_grp AS last_known_amount, PERCENT_RANK() OVER (PARTITION BY merchant, txn_type ORDER BY amount NULLS LAST) AS amount_percent_rank, LAG(amount, 1) OVER (ORDER BY amount, id) AS prev_amount FROM transactions WINDOW w_running AS (PARTITION BY merchant, txn_type ORDER BY amount DESC, id), w_grp AS (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, account_id, txn_type, amount, txn_time, is_flagged, amount_bucket, last_known_amount, amount_percent_rank FROM scored ORDER BY id DESC NULLS LAST
